mapper.select:
SELECT TOP 1 center_code
FROM erp_student
WHERE student_id = #{studentId}

SELECT TOP 1 grade_key
FROM erp_student
WHERE student_id = #{studentId}

SELECT schoolyear
FROM erp_bookstore_content
WHERE content_id = #{contentId}

SELECT exp_per_book
FROM erp_bookstore_exp_rule
WHERE schoolyear = #{schoolyear}

SELECT exp AS exp, level_no AS levelNo
FROM erp_bookstore_student_info
WHERE student_id = #{studentId}

SELECT badge_id
FROM erp_bookstore_student_badge
WHERE student_id = #{studentId}

SELECT COUNT(*) FROM erp_bookstore_recommend_log r JOIN erp_bookstore_content c ON c.content_id = r.content_id WHERE r.student_id = #{studentId} AND r.status = 'DONE' AND (
c.keywords LIKE '%' + #{kw} + '%'
)
